<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Roles & Access · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'team',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">ROLE AND SCOPE CONTROL</p><h1>Manager access</h1><p>Assign operational capability without granting full administrator access.</p></div><a class="button secondary" href="<?=esc(url_for('team'))?>">People</a></header><?php if($notice):?><div class="page-flash success"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><section class="panel"><?php foreach($accessRows as $row):?><details class="planning-row"><summary><strong><?=esc($row['name'])?></strong><small><?=esc(ucfirst($row['role']))?></small></summary><?php if($row['role']==='owner'):?><p>Owner access cannot be reduced here.</p><?php else:?><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="save_membership_access"><input type="hidden" name="membership_id" value="<?=$row['membership_id']?>"><label>Role<select name="role"><?php foreach(['admin','scheduler','supervisor','member'] as $role):?><option value="<?=$role?>" <?=$row['role']===$role?'selected':''?>><?=esc(ucfirst($role))?></option><?php endforeach;?></select></label><?php foreach(['can_schedule'=>'Build schedules','can_approve'=>'Approve requests','can_manage_payroll'=>'Manage payroll','can_manage_credentials'=>'Manage credentials','read_only'=>'Read only'] as $key=>$label):?><label class="check-label"><input type="checkbox" name="<?=$key?>" value="1" <?=!empty($row[$key])?'checked':''?>><span><?=$label?></span></label><?php endforeach;?><fieldset><legend>Location scope</legend><?php foreach($data['locations'] as $item):$checked=false;foreach($row['scopes'] as $scope)if($scope['scope_type']==='location'&&(int)$scope['resource_id']===(int)$item['id'])$checked=true;?><label class="check-label"><input type="checkbox" name="location_ids[]" value="<?=$item['id']?>" <?=$checked?'checked':''?>><span><?=esc($item['name'])?></span></label><?php endforeach;?></fieldset><fieldset><legend>Department scope</legend><?php foreach($data['departments'] as $item):$checked=false;foreach($row['scopes'] as $scope)if($scope['scope_type']==='department'&&(int)$scope['resource_id']===(int)$item['id'])$checked=true;?><label class="check-label"><input type="checkbox" name="department_ids[]" value="<?=$item['id']?>" <?=$checked?'checked':''?>><span><?=esc($item['name'])?></span></label><?php endforeach;?></fieldset><button class="button primary">Save access</button></form><?php endif;?></details><?php endforeach;?></section></main></body></html>
